$apps=@(
  @{Id="Google.Chrome";Source="winget"},
  @{Id="CodecGuide.K-LiteCodecPack.Standard";Source="winget"},
  @{Id="Microsoft.VCRedist.2015+.x64";Source="winget"},
  @{Id="Microsoft.VCRedist.2015+.x86";Source="winget"},
  @{Id="RARLab.WinRAR";Source="winget"}
)

$ok=$true
$timeoutSec=1200

foreach($a in $apps){
  $args=@("install","-e","--id",$a.Id,"-h","--accept-package-agreements","--accept-source-agreements","--source",$a.Source)
  $p=Start-Process -FilePath "winget.exe" -ArgumentList $args -PassThru -WindowStyle Hidden
  if(-not $p.WaitForExit($timeoutSec*1000)){
    try{$p.Kill()}catch{}
    $ok=$false
    break
  }
  if($p.ExitCode -ne 0){
    $ok=$false
    break
  }
}

if($ok){
